#!/usr/bin/env python3
"""Build the public educational playbook from supplied content and editorial notes."""
import re,json,html
from pathlib import Path
from thesis_notes import NOTES,PATTERNS,BEAR_BASE
R=Path(__file__).resolve().parents[1]; P=R/'playbook'; A=P/'assets'
E=html.escape
FAMILIES=[('trend','Trend continuation',1,15),('range','Trading ranges',16,28),('reversal','Major reversals',29,41),('traps','Trapped traders',42,45),('pressure','Buying & selling pressure',46,49),('opening','Openings & gaps',50,54),('magnets','Targets & magnets',55,57),('probes','Probes & confirmation',58,60)]
source=(R/'content/thesis-library.md').read_text()
items=[]
for m in re.finditer(r'^## (\d+)\. ([^\n]+)\n(.*?)(?=^## |^# |\Z)',source,re.M|re.S):
    i=int(m[1]); title=m[2].strip(); body=m[3].strip().strip('-').strip(); f=next(f for f in FAMILIES if f[2]<=i<=f[3])
    slug=f'{i:02d}-'+re.sub(r'[^a-z0-9]+','-',title.lower()).strip('-')
    items.append(dict(id=i,title=title,body=body,family=f[0],familyLabel=f[1],slug=slug,**NOTES[i]))
assert len(items)==60

def md(text):
    out=[]; listing=False
    for line in text.splitlines():
        line=line.strip()
        if not line or line=='---':continue
        bullet=line.startswith('* ') or line.startswith('- ')
        if listing and not bullet: out.append('</ul>');listing=False
        if bullet and not listing:out.append('<ul>');listing=True
        value=E(line[2:] if bullet or line.startswith('> ') else line)
        value=re.sub(r'\*\*(.+?)\*\*',r'<strong>\1</strong>',value)
        out.append(f'<li>{value}</li>' if bullet else f'<p>{value}</p>')
    if listing:out.append('</ul>')
    return ''.join(out)

def svg(t):
    prices,marks,stop,target,level=PATTERNS[t['diagram']]; prices=list(prices)
    bear=t['diagram'] in BEAR_BASE
    mirror=(t['direction']=='Short' and not bear) or (t['direction']=='Long' and bear)
    if mirror:prices=[100-v for v in prices];stop,target,level=100-stop,100-target,100-level
    wait=t['direction']=='Wait'; y=lambda v:350-v*2.85; x=lambda i:48+i*510/(len(prices)-1)
    s=[f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 900 420" role="img" aria-labelledby="title desc"><title id="title">{E(t["title"])} — teaching schematic</title><desc id="desc">Synthetic candles. Four numbered observations show context, pressure, setup, and decision. {E(t["trigger"])}. Invalidation: {E(t["invalidation"])}. No historical prices or performance are represented.</desc><rect width="900" height="420" rx="16" fill="#102b2c"/>']
    for v in [20,40,60,80]:s.append(f'<path d="M32 {y(v)}H868" stroke="#244344" stroke-width="1"/>')
    s.append('<text x="32" y="31" fill="#aac4bf" font-family="sans-serif" font-size="13">ILLUSTRATIVE PRICE ACTION · NOT MARKET DATA</text><path d="M600 48V364" stroke="#557675" stroke-dasharray="4 5"/><text x="630" y="55" fill="#aac4bf" font-family="sans-serif" font-size="12">POSSIBLE OUTCOMES</text>')
    s.append(f'<path d="M32 {y(level)}H588" stroke="#d7b878" stroke-dasharray="5 5" opacity=".7"/>')
    if t['diagram'] in {'ema','magap','channel','mtr'}:
        avg=prices[0]; pts=[]
        for j,p in enumerate(prices):avg=.23*p+.77*avg;pts.append(f'{x(j):.1f},{y(avg):.1f}')
        s.append(f'<polyline points="{" ".join(pts)}" fill="none" stroke="#d6b576" stroke-width="2"/><text x="34" y="382" fill="#d6b576" font-family="sans-serif" font-size="12">Gold curve: illustrative moving average</text>')
    for j,p in enumerate(prices):
        o=prices[j-1] if j else p-3
        if t['diagram'] in {'gapaccept','gapreject','gapclose'} and j==6:o=p-3 if p>o else p+3
        color='#7be0be' if p>=o else '#ec9690';xx=x(j);top=y(max(p,o));bottom=y(min(p,o));w=min(19,340/len(prices))
        s.append(f'<path d="M{xx:.1f} {y(max(p,o)+2):.1f}V{y(min(p,o)-2):.1f}" stroke="{color}" stroke-width="1.6"/><rect x="{xx-w/2:.1f}" y="{top:.1f}" width="{w:.1f}" height="{max(2,bottom-top):.1f}" rx="1" fill="{color}"/>')
    for n,j in enumerate(marks,1):
        yy=y(prices[j])-28 if n%2 else y(prices[j])+31
        s.append(f'<circle cx="{x(j):.1f}" cy="{yy:.1f}" r="12" fill="#f2ead7"/><text x="{x(j):.1f}" y="{yy+4:.1f}" text-anchor="middle" font-size="12" font-family="sans-serif" fill="#102b2c">{n}</text>')
    if wait:
        s.append('<text x="636" y="160" fill="#f2ead7" font-family="sans-serif" font-size="24">Wait for clarity.</text><text x="636" y="190" fill="#aac4bf" font-family="sans-serif" font-size="15">No entry is illustrated.</text>')
    else:
        entry=prices[-1]
        for val,label,color in [(target,'First objective','#7be0be'),(stop,'Invalidation','#ec9690')]:
            s.append(f'<path d="M{558} {y(entry):.1f}L640 {y(entry):.1f}L710 {y(val):.1f}H740" fill="none" stroke="{color}" stroke-width="2" stroke-dasharray="6 5"/><text x="748" y="{y(val)+4:.1f}" fill="{color}" font-family="sans-serif" font-size="14">{label}</text>')
        s.append(f'<circle cx="558" cy="{y(entry):.1f}" r="5" fill="#fff"/>')
    s.append('<text x="32" y="405" fill="#aac4bf" font-family="sans-serif" font-size="12">Time → · relative prices · schematic spacing does not imply a reward-to-risk ratio</text></svg>')
    return ''.join(s)

def shell(title,content,active='',detail=False):
    nav=''.join(f'<a href="/playbook/?family={key}"'+(' aria-current="page"' if active==key else '')+f'><span>{label}</span><small>{b-a+1:02d}</small></a>' for key,label,a,b in FAMILIES)
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{E(title)} | Pulapa Playbook</title><meta name="description" content="A visual field guide to 60 Brooks-style price-action theses. Study context, confirmation, invalidation and trade management."><link rel="icon" type="image/svg+xml" href="/assets/favicon.svg?v=2"><link rel="stylesheet" href="/playbook/assets/playbook.css"><script src="/playbook/assets/playbook.js" defer></script></head><body><a class="skip" href="#main">Skip to content</a><header class="mobile-header"><a href="/playbook/">P / THE PLAYBOOK</a><a href="#navigation">Menu ↓</a></header><aside class="sidebar" id="navigation"><a class="brand" href="/">P<span>PULAPA<small>Research & practice</small></span></a><div class="sidebar-label">THE FIELD GUIDE</div><a class="library-link" href="/playbook/">Thesis library <span>60 ↗</span></a><nav aria-label="Thesis families">{nav}</nav><div class="sidebar-bottom"><a href="/playbook/field-notes.html">Field notes & glossary ↗</a><a href="/playbook/checklist.html">Pre-trade checklist ↗</a><p>Context before pattern.<br>Evidence before conviction.</p><span class="status">● Educational reference</span></div></aside><main id="main" class="workspace">{content}<footer><span>PULAPA / PRICE ACTION PLAYBOOK</span><p>Supplied Brooks-style theses, edited for study. Synthetic illustrations; no tested edge or trading recommendation. <a href="/playbook/field-notes.html#sources">Sources & methodology</a></p></footer></main></body></html>'''

def chart(t):
    return f'''<figure class="chart"><img src="/playbook/assets/{t['slug']}.svg" alt="Annotated schematic for {E(t['title'])}: context, pressure, setup, decision." width="900" height="420"><figcaption>Teaching schematic · {('one direction illustrated; reverse the logic for the opposite side' if t['direction']=='Both' else t['direction'].lower()+' context')} · dashed paths are possibilities, not forecasts.</figcaption></figure><ol class="observations"><li><b>Context</b>{E(t['location'])}</li><li><b>Pressure</b>{E(t['evidence'])}</li><li><b>Setup</b>{E(t["location"])}. Require rejection or acceptance at the marked structure.</li><li><b>Decision</b>{E(t['trigger'])}</li></ol>'''

for t in items:
    (A/(t['slug']+'.svg')).write_text(svg(t))
    warning=''
    if t['id']==41:warning='<aside class="callout"><strong>Terminology correction</strong><p>An MA-gap bar does not touch the moving average. In a strong trend, the first gap bar on the countertrend side can precede a test of the trend extreme. A reversal needs additional evidence. The supplied draft below is retained for transparency; use this corrected interpretation.</p></aside>'
    if t['id'] in (58,59):warning='<aside class="callout"><strong>Advanced study: unconfirmed probe</strong><p>Study in simulation under a written risk plan. A failed probe is a completed loss, not an invitation to add. Compare with the confirmed-entry thesis #60.</p></aside>'
    pairs=[('Location',t['location']),('Evidence',t['evidence']),('Trigger',t['trigger']),('Invalidation',t['invalidation']),('First objective',t['target']),('Pass when',t['avoid'])]
    quick=''.join(f'<div><dt>{a}</dt><dd>{E(b)}.</dd></div>' for a,b in pairs)
    related=[v for v in items if v['family']==t['family'] and v['id']!=t['id']][:3]
    prev=items[t['id']-2] if t['id']>1 else None; nex=items[t['id']] if t['id']<60 else None
    paging=''.join(f'<a href="/playbook/{v["slug"]}.html"><small>{label}</small>{E(v["title"])} {arrow}</a>' for v,label,arrow in [(prev,'PREVIOUS','←'),(nex,'NEXT','→')] if v)
    body=f'''<div class="topline"><a href="/playbook/">← Thesis library</a><span>FIELD GUIDE / {t['id']:02d} OF 60</span></div><header class="detail-head"><p class="eyebrow">{E(t['familyLabel'])} <span class="pill">{t['direction']}</span></p><h1>{E(t['title'])}</h1><p class="lede">{E(t['location'])}. {E(t['evidence'])}.</p><nav class="jump" aria-label="On this page"><a href="#visual">Visual guide</a><a href="#reference">Quick reference</a><a href="#thesis">Full thesis</a><a href="#management">Management</a></nav></header>{warning}<section id="visual"><div class="section-title"><h2>Read the sequence.</h2><span>01 / OBSERVE → DECIDE</span></div>{chart(t)}</section><section id="reference"><div class="section-title"><h2>The decision map</h2><span>02 / QUICK REFERENCE</span></div><dl class="decision-map">{quick}</dl></section><section id="thesis" class="reading"><p class="eyebrow">03 / THE FULL ARGUMENT</p><h2>Thesis & participant logic</h2><p class="source-label">Supplied study draft · adapted Brooks-style prose, not a quotation from Al Brooks</p><div class="source-prose">{md(t['body'])}</div></section><section id="management" class="management"><p class="eyebrow">04 / FROM IDEA TO A PLAN</p><h2>Manage the thesis, not the need to be right.</h2><div class="management-grid"><div><h3>Before entry</h3><p>Write the structural invalidation and first realistic objective. Size to the loss you have already accepted, including costs and possible slippage. If the stop is unaffordable, reduce size or pass.</p></div><div><h3>After entry</h3><p>Reassess follow-through against the evidence above. Do not widen the stop or add because price “has gone too far.” A bounce to your average entry is not a market thesis.</p></div><div><h3>At the objective</h3><p>{E(t['target'])}. Decide ahead of time whether to exit or retain a defined remainder. Continue only while structure and follow-through support the trade.</p></div><div><h3>During review</h3><p>Record the entry-time chart, planned risk, maximum adverse excursion, actual exit, and whether the thesis was invalidated. Judge the decision separately from the outcome.</p></div></div><a class="button" href="/playbook/checklist.html">Open the pre-trade checklist ↗</a></section><section><h2>Study alongside</h2><div class="related">{''.join(f'<a href="/playbook/{v["slug"]}.html"><span>{v["id"]:02d}</span>{E(v["title"])} ↗</a>' for v in related)}</div></section><nav class="pagination" aria-label="Adjacent theses">{paging}</nav>'''
    (P/(t['slug']+'.html')).write_text(shell(t['title'],body,t['family'],True))

cards=''.join(f'''<article class="thesis-card" data-id="{t['id']}" data-family="{t['family']}" data-direction="{t['direction']}"><a href="/playbook/{t['slug']}.html"><div class="card-meta"><span>{t['id']:02d} / {E(t['familyLabel'])}</span><span class="pill">{t['direction']}</span></div><img src="/playbook/assets/{t['slug']}.svg" alt="" loading="lazy" width="900" height="420"><h2>{E(t['title'])}</h2><p>{E(t['location'])}.</p><div class="card-bottom">Read the thesis <span aria-hidden="true">↗</span></div></a></article>''' for t in items)
filters=''.join(f'<option value="{k}">{label}</option>' for k,label,a,b in FAMILIES)
body=f'''<div class="topline"><span>THE PRICE ACTION FIELD GUIDE</span><a href="/playbook/checklist.html">Before you trade ↗</a></div><header class="library-head"><p class="eyebrow">CONTEXT. CONFIRMATION. INVALIDATION.</p><h1>A thesis for the market.<br><em>A plan for yourself.</em></h1><p class="lede">60 Brooks-style scenarios, drawn and unpacked. Find the context, understand the participants, and know exactly what would prove the idea wrong.</p><div class="stats"><span><b>60</b> detailed theses</span><span><b>08</b> context families</span><span><b>60</b> visual guides</span></div></header><div class="start-strip"><span class="compass">↗</span><div><strong>Start with the market state.</strong><p>Trend, range, or transition? Then study location and pressure. A pattern name comes last.</p></div><a href="/playbook/field-notes.html">How to use this guide →</a></div><section class="catalog" aria-labelledby="catalog-title"><div class="section-title"><h2 id="catalog-title">The thesis library</h2><span id="result-count" role="status" aria-live="polite">60 THESES</span></div><form class="filters" role="search"><label class="search-label"><span class="sr-only">Search theses</span><input id="search" name="q" type="search" placeholder="Search context, setup, or thesis number…" autocomplete="off"><kbd>/</kbd></label><label><span class="sr-only">Market family</span><select id="family" name="family"><option value="">All contexts</option>{filters}</select></label><label><span class="sr-only">Direction</span><select id="direction" name="direction"><option value="">All directions</option><option>Long</option><option>Short</option><option>Both</option><option value="Wait">Stand aside</option></select></label><button type="reset" class="reset">Reset</button></form><p class="search-help">Search across the full thesis, trigger, invalidation, and management context.</p><div class="cards">{cards}</div><div id="empty" hidden><h3>No matching theses</h3><p>Try fewer words or reset the filters to explore another context.</p></div></section>'''
(P/'index.html').write_text(shell('Thesis library',body))
(A/'theses.json').write_text(json.dumps(items,ensure_ascii=False,indent=2))

notes='''<div class="topline"><a href="/playbook/">← Thesis library</a><span>THE WORKING METHOD</span></div><header class="detail-head"><p class="eyebrow">FIELD NOTES</p><h1>Read context.<br><em>Then read the pattern.</em></h1><p class="lede">This is a library of conditional arguments. It is a way to organize observation, not a list of automatic entries.</p></header><section class="reading"><h2>A four-pass reading process</h2><ol class="long-list"><li><strong>Classify the market.</strong> Identify trend, trading range, or transition. Assess the higher-timeframe location before zooming into a signal bar.</li><li><strong>Find the contested level.</strong> Identify support, resistance, a prior extreme, a breakout point, or a magnet. Ask which participants need continuation.</li><li><strong>Demand evidence.</strong> Read the quality of closes, overlap, follow-through, and failed attempts. “Too far” describes your perception, not proof of reversal.</li><li><strong>Write the disproof.</strong> Define the structural stop, realistic objective, and management before entry. If any is unclear, the thesis is incomplete.</li></ol><h2>Reading the illustrations</h2><p>Every chart is a synthetic candlestick schematic, not TradingView data, a replay, or a profitable backtest. Green candles close above their open; coral candles close below. Gold dashed lines mark a relevant structural reference. Four numbered markers map to the explanation beneath the chart.</p><p>The dashed paths show possible continuation and failure, not their probability. Relative spacing is instructional and does not imply a measurable reward-to-risk ratio. Bidirectional theses show one orientation. Real signals require the actual surrounding market.</p><h2>The trader’s equation</h2><div class="equation">Expected value = P(win) × average reward − P(loss) × average loss − costs</div><p>Probabilities and realized payoffs must come from suitable evidence. A 2R target does not establish an edge, and a high win rate does not compensate automatically for occasional large losses. R means the planned initial risk; changing it after entry destroys the comparison.</p><p>Numerical R targets in the supplied drafts are example assumptions, not validated thresholds. Gaps, slippage, fees, partial exits, and changing position size affect realized results.</p><h2 id="glossary">A compact glossary</h2><dl class="glossary"><dt>Always In</dt><dd>A directional assessment: which side a trader would favor if required to hold a position. It is not a requirement to trade.</dd><dt>H1 / H2 · L1 / L2</dt><dd>First and second resumption attempts in a pullback. High-bar and low-bar counting depends on intervening price action; location and trend matter.</dd><dt>Follow-through</dt><dd>Price action after a breakout that supports its direction.</dd><dt>Signal bar / entry bar</dt><dd>The bar supporting a proposed entry, and the subsequent bar during which entry occurs.</dd><dt>MA-gap bar</dt><dd>A bar that does not touch the moving average. Separation alone does not establish reversal.</dd><dt>Measured move</dt><dd>A projection from a prior price structure, used as a possible objective rather than a promise.</dd></dl><h2 id="sources">Sources & editorial boundaries</h2><p>The 60 full theses come from the supplied Brooks-style study library. They are not presented as quotations, verified probabilities, or rules personally endorsed by Al Brooks. The decision maps and charts are editorial learning aids.</p><p>Terminology was checked against the <a href="https://www.brookstradingcourse.com/price-action-trading-terms-glossary/">official Brooks Trading Course glossary</a>. In particular, thesis #41 includes a correction: a moving-average gap bar can precede a retest of the trend extreme. A reversal requires additional evidence.</p><p>The probe scenarios are advanced study material. Their presence here grants no permission to add to losers or override risk controls. This site does not establish your personal trading edge.</p><h2>Genesis governance</h2><p>Classification: operator_display / knowledge_graph. State: interpreted_doctrine for educational review only. Promotion allowed: false. No source or court gate has admitted these theses into runtime. TradingView, LuxAlgo, and strategy-tester P&amp;L are not decision authority here.</p></section>'''
(P/'field-notes.html').write_text(shell('Field notes & glossary',notes))
questions=[('Market state','Is this a trend, range, or transition? What does the higher timeframe change?'),('Always-In assessment','Which side has control, and what evidence supports that assessment?'),('Location','Am I at a meaningful edge, retest, extreme, or magnet?'),('Pressure','What do bodies, tails, overlap, and follow-through reveal?'),('Attempt','Is this a first attempt, second attempt, or repeated failure?'),('Expected outcome','Is the realistic outcome continuation, a scalp, or a reversal?'),('Trapped participants','Who needs an exit, and what price action confirms that pressure?'),('Entry trigger','What completed signal and subsequent action would permit entry?'),('Invalidation','What exact structure disproves the thesis, and is the loss affordable?'),('Target','Where is the first realistic opposing level? Is there enough room?'),('Trader’s equation','What evidence supports the probability and payoff assumptions after costs?'),('Management','What will I do on success, weak follow-through, and failure? Have I ruled out rescue additions?')]
checks=''.join(f'<label class="check-row"><input type="checkbox"><span><strong>{i:02d}. {a}</strong><span>{b}</span></span></label>' for i,(a,b) in enumerate(questions,1))
(P/'checklist.html').write_text(shell('Pre-trade checklist',f'''<div class="topline"><a href="/playbook/">← Thesis library</a><span>PAUSE / QUALIFY / DECIDE</span></div><header class="detail-head"><p class="eyebrow">THE PRE-TRADE CHECK</p><h1>Can you explain<br><em>the trade before it happens?</em></h1><p class="lede">Twelve questions to turn a pattern into a complete argument. Checking boxes does not validate a trade; the answers need evidence.</p></header><form class="checklist"><div class="section-title"><h2>Your qualification checklist</h2><button type="reset" class="reset">Clear checks</button></div>{checks}<p class="source-label">Checks stay only on this page and reset when you reload. No account or trade data is collected.</p></form><aside class="callout"><strong>A stop is a decision made in advance.</strong><p>If the thesis fails, accept the planned loss. “There must be a relief rally” is not confirmation. Return to observation before forming a new thesis.</p></aside>'''))
urls=['https://pulapa.online/']+['https://pulapa.online/playbook/'+('' if p.name=='index.html' else p.name) for p in sorted(P.glob('*.html'))]
(R/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n'+''.join('<url><loc>'+u+'</loc><lastmod>2026-09-23</lastmod></url>\n' for u in urls)+'</urlset>\n')
print('Built 60 thesis pages, 60 diagrams, library, field notes and checklist.')
